// Optimized app icon (192x192 RGBA PNG, generated from images/gpt-worker_icon.png).
// Delivered over same-origin HTTP to Web dashboards (/dashboard/<workspace_id>/icon.png
// and /dashboard/hub/icon.png) with public caching.

export const BRAND_ICON_PNG_BASE64 = "";

let cachedBytes = null;

export function brandIconPngBytes() {
  if (!cachedBytes) {
    if (typeof Buffer !== "undefined" && typeof Buffer.from === "function") {
      cachedBytes = new Uint8Array(Buffer.from(BRAND_ICON_PNG_BASE64, "base64"));
    } else {
      const binary = atob(BRAND_ICON_PNG_BASE64);
      const len = binary.length;
      const bytes = new Uint8Array(len);
      for (let i = 0; i < len; i++) {
        bytes[i] = binary.charCodeAt(i);
      }
      cachedBytes = bytes;
    }
  }
  return cachedBytes;
}
